new='''export async function toggleAcademicSave(userId:string,postId:string){ await requirePremium(userId); const current=await db.from("academic_saved_posts").select("post_id").eq("user_id",userId).eq("post_id",postId).maybeSingle(); if(current.error)fail("Não foi possível verificar a publicação salva."); if(current.data){const removed=await db.from("academic_saved_posts").delete().eq("user_id",userId).eq("post_id",postId);if(removed.error)fail("Não foi possível remover a publicação dos salvos.")}else{const added=await db.from("academic_saved_posts").insert({user_id:userId,post_id:postId});if(added.error)fail("Não foi possível salvar a publicação.")} const canonical=await db.from("academic_saved_posts").select("post_id").eq("user_id",userId).eq("post_id",postId).maybeSingle();if(canonical.error)fail("Não foi possível confirmar a publicação salva.");return {saved:Boolean(canonical.data)}; }'''
