new='''export async function toggleAcademicSupport(userId:string,postId:string){ await requirePremium(userId); const current=await db.from("academic_reactions").select("post_id").eq("user_id",userId).eq("post_id",postId).eq("reaction_type","support").maybeSingle();if(current.error)fail("Não foi possível verificar o acolhimento.");if(current.data){const removed=await db.from("academic_reactions").delete().eq("user_id",userId).eq("post_id",postId).eq("reaction_type","support");if(removed.error)fail("Não foi possível remover o acolhimento.")}else{const added=await db.from("academic_reactions").insert({user_id:userId,post_id:postId,reaction_type:"support"});if(added.error)fail("Não foi possível acolher a publicação.");const {data:post}=await db.from("academic_posts").select("user_id").eq("id",postId).maybeSingle();if(post?.user_id)await queueInAppNotification(post.user_id,userId,"Publicação acolhida","Sua publicação recebeu um Acolher.",{kind:"support",postId})}const canonical=await db.from("academic_reactions").select("post_id").eq("user_id",userId).eq("post_id",postId).eq("reaction_type","support").maybeSingle();if(canonical.error)fail("Não foi possível confirmar o acolhimento.");const counted=await db.from("academic_reactions").select("post_id",{count:"exact",head:true}).eq("post_id",postId).eq("reaction_type","support");if(counted.error)fail("Não foi possível atualizar a contagem de acolhimentos.");return {supported:Boolean(canonical.data),supportCount:Math.max(0,counted.count??0)}; }'''
